        }
      }
      csvString += ",";
    })
  })

  a.href = "data:application/csv;charset=utf-8," + encodeURIComponent(csvString);
  a.target = "_blank";
  a.download = "PT_Data_" + survey.code + ".csv";
  document.body.appendChild(a);
  a.click();
};

