        mustNotExist: mustNotExist
    };

    function mustExist(what, modelName, done) {
        'use strict';
        model[modelName].get(what).then(function(value) {
            let error = null;
            if (!value) {
                error = {
                    rule: 'mustExist',
                    actual: what,
                    expected: 'did not find ' + what + ' in model'
