  files.forEach(file => {
    const stat = fs.statSync(path.join(absDir, file))
    const id = stat.isDirectory() ? 'd' : 'f'
    const node = cache[absDir][id] || (cache[absDir][id] = [])
    node.push(file)
  })
  return {
    eachFile(cb) {
      cache[absDir].f.forEach(filename => {
        cb({
