  constructor(
    private readonly apollo: Apollo,
  ) { }

  getAuth = (): Auth | undefined => {
    try {
      const authString = localStorage.getItem('auth');

      if (authString === null) { return undefined; }

      return JSON.parse(authString) as Auth;
    } catch (e) {
      localStorage.removeItem('userId');

      return undefined;
