				this.logger.succ(`${serviceName} ${ver[1]} found`);
			} else {
				this.logger.warn(`${serviceName} not found`);
				this.logger.warn(`Regexp used for version check of ${serviceName} is probably messed up`);
			}
		} catch (e) {
			this.logger.warn(`${serviceName} not found`);
