  {
    public static Topology ToTopology(this string tpl)
    {
      if (tpl.Equals("xp0", StringComparison.InvariantCultureIgnoreCase))
      {
        return Topology.Xp0;
      }

      if (tpl.Equals("xp1", StringComparison.InvariantCultureIgnoreCase))
      {
