+    let mut mmax = 2;
+    while nn > mmax {
+        let istep = mmax << 1;
+        let theta = isign * (2.0 * PI / mmax as f64);
+        let wtemp = (0.5 * theta).sin();
+        let wpr = -2.0 * wtemp * wtemp;
+        let wpi = theta.sin();
+        let mut wr = 1.0;
+        let mut wi = 0.0;
+        for m in (1..mmax).step_by(2) {
+            for i in (m..(nn + 1)).step_by(istep) {
