pub fn report_error(err: Err<&[u8], u32>) {
    match err {
        Err::Code(_) => {
            println!("Parsing error: Unknown origin");
        }
        Err::Node(_, n) => {
            println!("Parsing error: Unknown origin");
            for e in n {
                report_error(e);
            }
        }
        Err::Position(_, p) => {
            println!(
                "Parsing error: When input is {:?}",
                String::from_utf8_lossy(p).into_owned()
            );
        }
        Err::NodePosition(_, p, n) => {
            println!(
                "Parsing error: When input is {:?}",
                String::from_utf8_lossy(p).into_owned()
            );
            for e in n {
                report_error(e);
            }
        }
    }
}

