// Creates sequence of values from [0, n)
func newSeq(n int) seq {
	return seq{make([]int, n, n)}
}

func (me seq) Index(i int) (ret int) {
	ret = me.i[i]
	if ret == 0 {
		ret = i
	}
	return
}

func (me seq) Len() int {
	return len(me.i)
}

// Remove the nth value from the sequence.
