	_, err := os.Stat(path)
	return err == nil
}

// createdir is used when the existence of a directory is absolutely required.
func createdir(dir string) string {
	if !exists(dir) {
		err := os.MkdirAll(dir, 0700)
		if err != nil {
			pr("Fatal: Couldn't create directory %s", dir)
