func ChoosePlug(plugs []Plug) Plug {
	rand.Seed(time.Now().Unix())
	// Split plugs into default and custom ads
	var defaults []Plug
	var customs []Plug
	for i := 0; i < len(plugs); i++ {
		if plugs[i].IsDefault() {
