    $old = $global:OLDPWD
    $global:OLDPWD = Get-Location | select -ExpandProperty Path

    Switch ($path) {
        "-" {
            Set-Location $old
        }
        "" {
            Set-Location ~
        }
        default {
            try {
                Set-Location $path
            }
            catch {
                $global:OLDPWD = $old
                throw
            }
        }
    }

}

