function Get-GitBranch
{
	$branch = git branch -a 2> $null | Where-Object {$_ -match "^\*"}
	if ($branch -eq $null) {
		return $null
	}
	
	$branch = $branch.Substring(2)
	
	if ($branch -match "^\(.*\)$") {
		$branch = (git name-rev HEAD 2> $null).Substring(5)
	}
	
	$workdir = ([io.fileinfo](git workdir 2> $null)).basename
	
	"$($workdir):$($branch)"
}

function prompt
{
	$exit = $LastExitCode
	if ($exit -eq $null) {
		$exit = 0
	}
	
	$git = Get-GitBranch
	if ($git -ne $null) { 
		$git = "[$git] "
	}
	
	# Reset $LastExitCode so we don't get confusing things happening because of stuff we've run
	cmd /c "exit $($exit)"
	
	# Right prompt
	$rprompt = "[$($exit)]"
	Write-Host (" " * ($host.ui.rawui.windowsize.width - $rprompt.length - 1) + "$($rprompt)`r") -nonewline
	
	# Left prompt
	"$($git)$($executionContext.SessionState.Path.CurrentLocation) $('$' * ($nestedPromptLevel + 1)) "
}

