                $tmp = $f[$i],$f[$i+1] -replace '^([^:]+:\s)'

                New-Object PSObject -Property @{
                    Name = $tmp[0]
                    State = $tmp[1]
                }
            }

            $feature | Export-Clixml $cachepath

            return $feature
        }
        catch
        {
            Throw
        }

    }
}

